#' Candidate spectral features
#'
#' Defines the per-date features whose temporal contrast across field borders is ranked
#' by [fb_rank_contrast()]. The default set, used to develop and validate the method,
#' holds the bands and the normalised differences of all band pairs,
#' `(a - b) / (a + b + 1e-4)`. With `set = "svid"`, published spectral indices from the
#' catalogue of the `svid` package (and, optionally, expressions generated by an `svid`
#' grammar) that can be computed from the available bands are added.
#'
#' @param bands Band names of the stack (Sentinel-2 names such as `"B04"`).
#' @param set `"nd"` (bands and normalised differences) or `"svid"`.
#' @param grammar Optional `svid_grammar` object whose expressions are added when
#'   `set = "svid"`; keep it small, because every expression is ranked.
#' @return A data frame with columns `name`, `expr` (an R expression in the band names)
#'   and `type` (`"band"`, `"nd"`, `"svid"`).
#' @examples
#' fs <- fb_feature_set(c("B02", "B03", "B04", "B08"))
#' fs
#' if (requireNamespace("svid", quietly = TRUE)) {
#'   sv <- fb_feature_set(fb_example_bands(), set = "svid")
#'   table(sv$type)
#'   head(sv[sv$type == "svid", ])
#' }
#' @export
fb_feature_set <- function(bands, set = c("nd", "svid"), grammar = NULL) {
  set <- match.arg(set)
  b <- data.frame(name = bands, expr = bands, type = "band")
  pr <- utils::combn(seq_along(bands), 2)
  nd <- data.frame(name = sprintf("ND(%s,%s)", bands[pr[1, ]], bands[pr[2, ]]),
                   expr = sprintf("(%s - %s) / (%s + %s + 1e-4)", bands[pr[1, ]], bands[pr[2, ]], bands[pr[1, ]], bands[pr[2, ]]),
                   type = "nd")
  out <- rbind(b, nd)
  if (set == "svid") out <- rbind(out, svid_features(bands, grammar))
  out[!duplicated(out$name), , drop = FALSE]
}

# Published indices (and optional grammar expressions) from svid, rewritten in band names.
svid_features <- function(bands, grammar = NULL) {
  if (!requireNamespace("svid", quietly = TRUE)) {
    stop("set = \"svid\" needs the svid package: remotes::install_github(\"ehsanrahimi666/_SVID\")")
  }
  native <- get(".svid_sensor_defs", envir = asNamespace("svid"))()$sentinel2$native
  sym <- names(native)[native %in% bands]
  if (!length(sym)) return(data.frame(name = character(), expr = character(), type = character()))
  # the catalogue of published indices (lazy data of svid; read directly so that svid need
  # not be attached), restricted to indices whose bands are all available
  cat_df <- getExportedValue("svid", "asi_indices")
  ok_bands <- vapply(strsplit(cat_df$band_list, ","), function(b) all(trimws(b) %in% sym), logical(1))
  cat_df <- cat_df[ok_bands, , drop = FALSE]
  ex <- stats::setNames(as.character(cat_df$formula), paste0("svid:", cat_df$short_name))
  if (!is.null(grammar)) {
    pool <- as.character(svid::svid_generate(grammar))
    ex <- c(ex, stats::setNames(pool, paste0("svid:", pool)))
  }
  rewrite <- function(e) {
    p <- tryCatch(str2lang(e), error = function(err) NULL)
    if (is.null(p)) return(NA_character_)
    vars <- all.vars(p)
    if (!all(vars %in% sym)) return(NA_character_)
    env <- stats::setNames(lapply(native[vars], as.name), vars)
    paste(deparse(do.call(substitute, list(p, env)), width.cutoff = 500L), collapse = "")
  }
  e2 <- vapply(ex, rewrite, "")
  keep <- !is.na(e2)
  # keep expressions that evaluate to finite values on typical reflectances
  probe <- stats::setNames(as.list(seq(0.05, 0.45, length.out = length(bands))), bands)
  ok <- vapply(e2[keep], function(e) {
    v <- tryCatch(eval(str2lang(e), probe), error = function(err) NA_real_)
    length(v) == 1L && is.finite(v)
  }, TRUE)
  data.frame(name = names(e2)[keep][ok], expr = unname(e2[keep][ok]), type = "svid")
}

# Values of features (rows of defs) for given rows of a block value matrix X (cells x
# dates*bands, dates outer) and one date m: a cells x features matrix.
feature_matrix <- function(defs, X, m, bands, rows = NULL) {
  nb <- length(bands)
  cols <- ((m - 1) * nb + 1):(m * nb)
  Xm <- if (is.null(rows)) X[, cols, drop = FALSE] else X[rows, cols, drop = FALSE]
  env <- stats::setNames(lapply(seq_len(nb), function(j) Xm[, j]), bands)
  out <- vapply(defs$expr, function(e) {
    v <- eval(str2lang(e), env)
    if (length(v) == 1L) v <- rep(v, nrow(Xm))
    as.numeric(v)
  }, numeric(nrow(Xm)))
  if (is.null(dim(out))) out <- matrix(out, nrow = nrow(Xm))
  colnames(out) <- defs$name
  out
}

# Per-pixel variables of the cropland model: bands plus NDVI, ND(B08,B11), ND(B11,B12) when
# the bands are available.
cropland_variables <- function(bands) {
  v <- data.frame(name = bands, expr = bands, type = "band")
  idx <- list(NDVI = c("B08", "B04"), NDMI = c("B08", "B11"), NDSW = c("B11", "B12"))
  for (nm in names(idx)) {
    ab <- idx[[nm]]
    if (all(ab %in% bands)) {
      v <- rbind(v, data.frame(name = nm, expr = sprintf("(%s - %s) / (%s + %s + 1e-4)", ab[1], ab[2], ab[1], ab[2]), type = "nd"))
    }
  }
  v
}

# Temporal statistics (10th, 50th, 90th percentile and SD over clear dates) of the
# cropland variables for the given cells of a block: a cells x (4 * variables) matrix.
cropland_features <- function(vars, blk, rows = NULL) {
  n <- if (is.null(rows)) nrow(blk$X) else length(rows)
  out <- list()
  for (k in seq_len(nrow(vars))) {
    A <- matrix(NA_real_, n, blk$M)
    for (m in seq_len(blk$M)) {
      v <- feature_matrix(vars[k, , drop = FALSE], blk$X, m, blk$bands, rows)[, 1]
      cl <- if (is.null(rows)) blk$C[, m] else blk$C[rows, m]
      v[!cl] <- NA_real_
      A[, m] <- v
    }
    st <- .row_stats_cpp(t(A), c(0.1, 0.5, 0.9))
    colnames(st) <- paste0(vars$name[k], c("_p10", "_p50", "_p90", "_sd"))
    out[[k]] <- st
  }
  do.call(cbind, out)
}
